    for i in range(10):
        if str(i * num1) == str(i * num2):
            count += 1
    greaterCount, equalCount = [0, 0]
    for j in range(min(len1, len2)):
        if str(i * num1)[j] >= (i * num2)[j]:
            greaterCount[j] = count
        else:
            equalCount[j] = count
