import heapq

def find_min_cost(N, K, S, A, C):
    disjoint = {i: i for i in range(N)}
    graph = [[] for _ in range(N)]

    for i, alliance in enumerate(A):
        for j, cost in enumerate(C[i]):
            if (alliance, j) not in [-1, 0]:
                graph[i].append((alliance, j))
                if cost != -1:
                    union(disjoint, i, alliance)
                else:
                    blacklist(disjoint, i, alliance)
                add_edge(disjoint, graph, i, cost)
                add_edge(disjoint, graph, alliance, 0)

    cost_to_targ = [-1] * N
    visited = [False] * N

    def dijkstra(disjoint):
        min_heap = []
        heapq.heappush(min_heap, (0, S))
        visited[S] = True

        while min_heap:
            cost, current = heapq.heappop(min_heap)
            if current == -1 or visited[current]:
                continue

            visited[current] = True
            cost_to_targ[current] = cost

            for adjacent_node, weight in graph[current]:
                if disjoint[adjacent_node] == current or adjacent_node == -1:
                    heapq.heappush(min_heap, (cost+weight, adjacent_node))

    dijkstra(disjoint)

    return cost_to_targ

def union(disjoint, a, b):
    a_root = find(disjoint, a)
    b_root = find(disjoint, b)
    disjoint[b_root] = a_root

def blacklist(disjoint, child, parent):
    blacklist_set = set()
    blacklist(disjoint, 0, child, parent, blacklist_set)

def blacklist(disjoint, root, child, parent, invalid_set):
    if disjoint[child] == parent and child not in invalid_set:
        invalid_set.add(child)

def add_edge(disjoint, graph, u, cost):
    u_root = find(disjoint, u)
    for v, w in graph[u]:
        if cost_to_targ[v] != -1 and w != -1:
            v_root = find(disjoint, v)
            if v_root == u_root:
                disjoint[v_root] = v_root
        else:
            graph[u].append((v, w))

        if w != -1:
            u_root = find(disjoint, u)
            v_root = find(disjoint, v)
            if w != -1:
                if u_root != v_root:
                    disjoint[v_root] = u_root

