def power_mod(x, k, mod):
    result = 1
    x %= mod
    while k:
        if k & 1:
            result = result * x % mod
        x = x * x % mod
        k >>= 1
    return result

def sum_of_possibilities(n, m, k):
    dp = [[0] * (m+1) for _ in range(n+1)]
    dp[0][0] = 1

    for i in range(n+1):
        for j in range(m+1):
            if j >= dp[i-1][0]:
                dp[i][j] += dp[i-1][j-1]
            if j >= dp[i-1][1]:
                dp[i][j] += dp[i-1][j-1]*j
            if j >= dp[i-1][2]:
                dp[i][j] += dp[i-1][j-1] * j**2
            dp[i][j] %= mod

    result = 0
    for i in range(1, m+1):
        result += power_mod(dp[n][i], k, mod)
        result %= mod

    return result

