def find_exit_station(n, m, s, t):
    while s > 1 and n > 1:
        if (s + t) % n < t:
            s = (n * ((s + t) % n - 1)) % n + 1
        else:
            s = (s * 2 + t) % n
        t -= 1

    if s == 1 and t < m - 1 and n - t <= m:
