            for v in constraint:
                if m_constraints[v-1] == 0:
                    constraint_satisfied = False
                    break
            if not constraint_satisfied:
                break

        if constraint_satisfied:
            min_max_lists.append(values)

    # Find the list with the minimum max value
    min_max_list = min(min_max_lists, key=lambda l: max(l))

