@lru_cache(maxsize=None)
def combMod(n, k, mod):
    if k > n:
        return 0
    elif k > 0:
        return comb(n, k) * pow(n - k + 1, mod - 2, mod) % mod
    elif k == 0:
        return 1

@lru_cache(maxsize=None)
def catalanMod(n, mod):
    if n == 0:
        return 1
    else:
        return combMod(2 * n, n - n // 2, mod) % mod

@lru_cache(maxsize=None)
def fibonacciMod(n, mod):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return (fibonacciMod(n - 1, mod) * (5 * mod + 1) % mod + fibonacciMod(n - 2, mod) * 2 * mod + fibonacciMod(n - 3, mod)) % mod

