import sys
from collections import defaultdict

def solve(n, k, s, alliances, costs):
    indegree = defaultdict(int)
    adjacency_list = [[] for _ in range(n)]

    for i in range(n):
        for j in range(k):
            if j == alliances[i]:
                continue
            adjacency_list[i].append(j)
            indegree[j] += 1

    def bellman_ford(start, distances):
        infinity = sys.maxsize * (10000 + 1)
        distances[start] = 0
        for _ in range(k-1):
            for u in range(n):
                for v, w in adjacency_list[u]:
                    distances[v] = min(distances[v], distances[u] + w)
        return distances

    distances = bellman_ford(0, [infinity] * n)
    minimum_distances = [sys.maxsize] * n

    def relax(u, a, b):
        if distances[a] < minimum_distances[b] or distances[b] < minimum_distances[a]:
            minimum_distances[b] = min(minimum_distances[a], distances[a] + costs[a][b])

    for i in range(1, k):
        for u in range(n):
            for v in adjacency_list[u]:
                relax(u, v[0], v[1])

    return ' '.join(map(str, map(lambda x: '-1' if x == sys.maxsize else str(x), minimum_distances)))

