        # 因此最少的最大的差值是(最大n - 1)/k
        modulus = (n - 1) // k
        gcd_result = a[0] % i
        for gcd_num in range(modulus, -1, -1):
            full_term = gcd_result * gcd(gcd_result, i)
            if full_term >= k:
                break
        return rem_k(n, k, i, full_term)

def rem_k(n, k, i, full_term):
    from fractions import Fraction

