def find_k_points(points, k):
    dp = defaultdict(list)
    visited = set()
    result = []

    def dfs(index):
        if len(visited) == k:
            return
        visited.add(index)
        for neighbor in dp[index]:
            if neighbor not in visited:
                dfs(neighbor)
        visited.remove(index)
        result.append(index+1)

    for i in range(len(points)):
        for neighbor in dp[points[i][1]]:
            if neighbor not in visited:
                dp[neighbor].append(points[i][0])
        if i+1 not in visited:
            dp[i+1] = [i+2]

