def dijkstra(graph, s, T):
    dist = {v: float('inf') for v in graph}
    dist[s] = 0
    pq = [(0, s)]

    while pq:
        d, u = pq.pop(0)
        if d > dist[u]: continue

        for v, c in graph[u]:
            if dist[u] + c < dist[v]:
                dist[v] = dist[u] + c
                pq.append((dist[v], v))

    return dist

