    inverse = pow(mod-1, k, mod)  # avoid division by returning mod^k elements
    for i in range(1, k+1):
        for j in range(1, i+1):
            binom[j] = (binom[j-1] * i) % mod  # Calculate general binomial coefficient, use tail recursive.

    pow_binom = [(1, 1)]  # equivalent to inverse array above, allows for updating binom coincidentally
    for pos in reversed(range(0, n+1)):
        if pos >= 2:
            count = n
            mpow = pos
            while mpow <= k:
                mul = 1
                while mul <= mpow and pow_binom[-int(pos) % len(pow_binom)][0]:
                    mul *= pos // (mpow * pow_binom[-int(pos) % len(pow_binom)][1] + 1)
                    mpow *= pow_binom[-int(pos) % len(pow_binom)][1]
                pow_binom.append((binom[::-1].pop(), mul // mpow))
            binom.append(binom[::-1].pop() // binom[-2])

    return len(list(filter(lambda x: x, retain_even((invert * binom[-1]) % mod))))

def retain_even(nums):
    ret = 0
    for index in range(len(nums)):
        if (ret or not nums[index]) and index % 2 == 0:
            ret += nums[index]
    return [nums[i:] for i in range(-1, -len(nums)-1, -1) if not ret % 2]

