from collections import defaultdict
import heapq

def dijkstra(adj, src):
    dist = defaultdict(lambda : float('inf'))
    dist[src] = 0
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            new_d = d + w
            if new_d < dist[v]:
                dist[v] = new_d
                heapq.heappush(pq, (new_d, v))
    return dist

def solve():
    n, k = map(int, input().split())
    points = []
    for _ in range(n):
        x, y = map(int, input().split())
        if x != 0 or y != 0:
            points.append((x, y))
    if k == 1:
        print(1)
        return

    dist = {x: float('inf') for x in range(1, k+1)}
    adj = defaultdict(list)

    def neighbor(i):
        if i-1 >= 0:
            yield (i-1, dist[i-1])
        if len(points) > i+1:
            yield (i+1, dist[i])
        if i+1 < k:
            yield (i+1, dist[i+1])

    for i in range(1, k+1):
        min_dist = float('inf')
        conn_numb, conn_d = -1, float('inf')
        for j in neighbor(i):
            w = j[1]
            if w < min_dist:
                min_dist = w
                conn_numb, conn_d = j
        dist[i] = min_dist
        adj[conn_numb - 1].append((conn_numb, min_dist))
        adj[conn_numb].append((conn_numb - 1, min_dist))

    ans = []
    delete_numb = {}
    visited = set()
    visit_dist = defaultdict(lambda : float('inf'))
    visit_dist[0] = 0

    def dfs(i):
        if visit_dist[i] == float('inf'):
            visit_dist[i] = dist[i]
            ans.append(i)
            delete_numb[i] = k - 1
        for j, w in adj[i]:
            if j in visited and visit_dist[j] != float('inf'):
                continue
            if j in delete_numb:
                continue
            visit_dist[j] = 2 * dist[i]
            visit_dist[j] += w
            delete_numb[j] = k - 2
            dfs(j)

    dfs(0)
    for i in range(len(points)):
        if i not in delete_numb and visit_dist[i] + dist[i] < visit_dist[points[i][0]]:
            delete_numb[i] = i

    answer = []
    for i in sorted(delete_numb):
        answer.append(i)
    print(*answer)

