    best_chk_ops = (0, 0)

    for chk_x, chk_y in points:
        chk_moves = 0
        for pt_x, pt_y in points:
            aux_moves = abs(chk_x - pt_x) + abs(chk_y - pt_y)
            if aux_moves < 2 * c + 1:
                chk_moves += aux_moves // (2 * c + 1)
            elif abs(chk_x - pt_x) == 2 * c + 1:
                chk_moves += 1
            elif abs(chk_y - pt_y) == 2 * c + 1:
                chk_moves += 1

        if chk_moves < min_moves:
            min_moves = chk_moves
            best_chk_ops = (chk_x, chk_y)

