import sys

class Circle:
    def __init__(self, x, y, closest, distance):
        self.center = complex(x, y)
        self.closest = closest
        self.distance = distance
        self.inner_graph = set()

    def add_to_closest(self, intersection):
        self.closest = intersection
        self.inner_graph = set()

    def add_to_inner_graph(self, intersection):
        self.inner_graph.add(intersection)

    def union_circle_with(self, other):
        other.add_to_closest(self)
        other.add_to_inner_graph(self)

    def distance_to(self, point):
        return abs(self.center - point)

def find_smallest_diameter():
    n, k = map(int, sys.stdin.readline().split())
    points = {int(x): Point(x, y) for x, y in enumerate(map(int, sys.stdin.readline().split()), 1)}

    circles = {}
    visited = set()

    for point in points.values():
        for closest in circles.keys():
            if closest.distance_to(point) > point.distance_to(circles[closest].edge.center):
                if point.distance_to(circles[closest].edge.center) > circles[closest].edge.distance_to(point):
                    circles[point] = circles[closest]
                    closest.union_circle_with(point)
                    visited.add(closest)
                    break
        else:
            circles[point] = Circle(point, Point(0, 0), point.distance_to(Point(0, 0)), point.distance_to(Point(0, 0)))

        for point2 in points.values():
            if not (point in point2.inner_graph or point2 in visited):
                if point not in circles[point2]:
                    circles[point2] = Circle(point2, Point(0, 0), point2.distance_to(Point(0, 0)), point2.distance_to(Point(0, 0)))
                if circle1 := circles[point].closest:
                    if not point2 in circles[circle1].inner_graph:
                        circles[point2].add_to_closest(circles[circle1].closest)
                        circles[circle1].union_circle_with(circles[point2])
                        visited.add(circles[point2])

        d = max([point.distance_to(closest.edge.center) for closest in circles.values()])

        visited.clear()

    return d

print(find_smallest_diameter())
