import re

def calculate_expression(expression):
    # Remove parentheses and collect all numbers and operators
    tokens = re.findall(r'\d+|[+\-*/()]', expression)
    numbers = [int(num) for num in tokens if num.isdigit()]
    operators = [t for t in tokens if t in '+-*/()']

    def evaluate(expression):
        if '(' in expression:
            left, right = expression.split('(')
            right = right.rstrip(')')
            return evaluate(right) + evaluate(left)
        else:
            stack = []
            for token in expression:
                if token.isdigit():
                    stack.append(int(token))
                elif token in operators:
                    operator = operators.index(token)
                    right = stack.pop()
                    left = stack.pop()
                    if len(stack) > 1:
                        raise ValueError("Invalid expression: stack is not empty after evaluating")
                    if operator == 0:
                        stack.append(left + right)
                    elif operator == 1:
                        stack.append(left - right)
                    elif operator == 2:
                        stack.append(left * right)
                    elif operator == 3:
                        stack.append(left // right)
            return stack[0]

    # Evaluate the expression inside the parentheses first for any nested problems
    expression = expression.replace("(", "( ").replace(")", " )")
    solve_expression = calculate_expression(expression) if '(' in expression else calculate_expression(expression.replace('-1', '1')).replace('-', '+')
    return solve_expression

